// Guards the links generated by src/shared/autolink.plugin.ts. Nothing else in
// the pipeline looks at generated markup: `astro check` sees the plugin's
// types, not its output, and html-validate does not catch nested anchors here.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';

import { BASE } from '../src/shared/config.ts';

const DIST = 'dist';

// Expected site-wide total, and how far the count may drift before someone
// looks. Update both numbers when content changes move the count on purpose;
// the point of the check is that a silent collapse to zero — the plugin
// falling out of astro.config.ts — cannot pass unnoticed.
const EXPECTED_TOTAL = 134;
const TOLERANCE = 0.2;

// These two page templates render several Markdown documents onto one page, so
// the same term can be linked once per document and still be a first
// occurrence. Every other page renders exactly one body.
const AGGREGATE_PAGES = [/^faq\/[^/]+\/index\.html$/, /^factory-settings\/[^/]+\/index\.html$/];

const ANCHOR_BOUNDARY = /<a\b[^>]*>|<\/a>/g;
const AUTOLINK_ANCHOR = /<a\b[^>]*\bdata-autolink="[^"]*"[^>]*>/g;
const HREF = /\bhref="([^"]*)"/;
const HEADING = /<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/g;
const PRE = /<pre\b[^>]*>([\s\S]*?)<\/pre>/g;

const walk = (directory) =>
  readdirSync(directory).flatMap((name) => {
    const entry = path.join(directory, name);
    return statSync(entry).isDirectory() ? walk(entry) : [entry];
  });

const failures = [];
const htmlFiles = walk(DIST).filter((file) => file.endsWith('.html'));
let total = 0;

for (const file of htmlFiles) {
  const html = readFileSync(file, 'utf8');
  const where = path.relative(DIST, file);
  const report = (message) => failures.push(`${where}: ${message}`);

  let depth = 0;
  for (const [tag] of html.matchAll(ANCHOR_BOUNDARY)) {
    if (tag === '</a>') depth = Math.max(0, depth - 1);
    else if (++depth > 1) report('nested <a> elements');
  }

  for (const [, , inner] of html.matchAll(HEADING)) {
    if (inner.includes('data-autolink')) report('auto-link inside a heading');
  }

  for (const [, inner] of html.matchAll(PRE)) {
    if (inner.includes('data-autolink')) report('auto-link inside <pre>');
  }

  const byHref = new Map();
  for (const [tag] of html.matchAll(AUTOLINK_ANCHOR)) {
    total += 1;
    const href = HREF.exec(tag)?.[1] ?? '';

    if (BASE && !href.startsWith(`${BASE}/`)) report(`auto-link misses the base path — "${href}"`);

    byHref.set(href, (byHref.get(href) ?? 0) + 1);
  }

  if (!AGGREGATE_PAGES.some((pattern) => pattern.test(where))) {
    for (const [href, count] of byHref) {
      if (count > 1) report(`${count} auto-links to "${href}" on one page`);
    }
  }
}

const lowest = Math.floor(EXPECTED_TOTAL * (1 - TOLERANCE));
const highest = Math.ceil(EXPECTED_TOTAL * (1 + TOLERANCE));

console.log(`Checked ${htmlFiles.length} pages, found ${total} auto-links.`);

if (total < lowest || total > highest) {
  failures.push(
    `site-wide: ${total} auto-links, expected ${EXPECTED_TOTAL} (allowed ${lowest}-${highest}). ` +
      'Update EXPECTED_TOTAL in this script if the change was intended.'
  );
}

if (failures.length > 0) {
  console.error(`\n${failures.length} auto-link problem(s):`);
  for (const failure of failures) console.error(`  ${failure}`);
  process.exit(1);
}

console.log('Auto-links are well-formed.');
